export const config = { runtime: 'edge' };

const GEREKEN = 3;   // beş kelimeden kaçı yeterli

const ALLOWED = ['https://raufenc.com', 'https://www.raufenc.com'];
function originOk(req) {
  const host = req.headers.get('origin') || req.headers.get('referer') || '';
  if (!host) return false;
  if (ALLOWED.some(a => host.indexOf(a) === 0)) return true;
  if (/^https?:\/\/(localhost|127\.0\.0\.1)(:\d+)?/.test(host)) return true;
  if (/^https:\/\/[a-z0-9-]+\.vercel\.app/.test(host)) return true;
  return false;
}

/* En iyi-çaba hız sınırı — kaba kuvvetle deneme yapmayı pahalılaştırır */
const HITS = new Map();
function rateLimited(req) {
  const ip = (req.headers.get('x-forwarded-for') || 'anon').split(',')[0].trim();
  const now = Date.now(), win = 60000, max = 20;
  const arr = (HITS.get(ip) || []).filter(t => now - t < win);
  arr.push(now);
  HITS.set(ip, arr);
  if (HITS.size > 5000) HITS.clear();
  return arr.length > max;
}

/* ── Metin normalleştirme ──────────────────────────────────────
   Şapkalı ve Türkçe özel harfleri ASCII'ye katlar: "mefkûre" de
   "mefkure" de, "düğüm" de "dugum" de aynı kabul edilir. Türkçe
   klavyesi olmayan kullanıcı da geçebilir. */
const KATLA = {
  'â':'a','ā':'a','ä':'a','à':'a','á':'a',
  'î':'i','ī':'i','ï':'i','ì':'i','í':'i','ı':'i',
  'û':'u','ū':'u','ü':'u','ù':'u','ú':'u',
  'ê':'e','ë':'e','è':'e','é':'e',
  'ô':'o','ö':'o','ò':'o','ó':'o',
  'ç':'c','ğ':'g','ş':'s'
};
function normalle(s) {
  return String(s == null ? '' : s)
    .slice(0, 400)
    .replace(/İ/g, 'i').replace(/I/g, 'i')
    .toLowerCase()
    .replace(/[âāäàáîīïìíıûūüùúêëèéôöòóçğş]/g, c => KATLA[c] || c)
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

/* Kartın kaç kelimesi kullanıcının yazdığı metinde geçiyor */
function tutan(kart, metin, jetonlar) {
  let n = 0;
  for (const w of kart.w) {
    const k = normalle(w[0]);
    if (!k) continue;
    if (k.indexOf(' ') >= 0 ? metin.indexOf(k) >= 0 : jetonlar.has(k)) n++;
  }
  return n;
}

function esles(seri, girdi) {
  const kilitli = KILITLI[seri];
  if (!kilitli) return { ok: false, sebep: 'seri' };

  const metin = normalle(girdi);
  const jetonlar = new Set(metin ? metin.split(' ') : []);
  if (jetonlar.size < GEREKEN) return { ok: false, sebep: 'kisa' };

  const bulunan = kilitli
    .map(k => ({ kart: k, n: tutan(k, metin, jetonlar) }))
    .filter(x => x.n >= GEREKEN)
    .sort((a, b) => b.n - a.n);

  if (bulunan.length === 1) return { ok: true, kart: bulunan[0].kart.t };
  if (bulunan.length > 1) {
    /* Net kazanan varsa onu al (ör. 5 tutan vs 3 tutan) */
    if (bulunan[0].n > bulunan[1].n) return { ok: true, kart: bulunan[0].kart.t };
    return { ok: false, sebep: 'coklu' };
  }

  /* Ücretsiz kartlardan yazmış olabilir — nazik uyarı için bak */
  const acik = (ACIK[seri] || []).find(k => tutan(k, metin, jetonlar) >= GEREKEN);
  if (acik) return { ok: false, sebep: 'acik', kart: acik.t };

  return { ok: false, sebep: 'yok' };
}

const json = (obj, kod) => new Response(JSON.stringify(obj), {
  status: kod || 200,
  headers: { 'content-type': 'application/json; charset=utf-8', 'cache-control': 'no-store' }
});

export default async function handler(req) {
  if (req.method !== 'POST') return json({ ok: false, hata: 'yontem' }, 405);
  if (!originOk(req))        return json({ ok: false, hata: 'kaynak' }, 403);
  if (rateLimited(req))      return json({ ok: false, hata: 'yavasla' }, 429);

  let g;
  try { g = await req.json(); } catch { return json({ ok: false, hata: 'govde' }, 400); }

  const seri = String(g && g.seri || '').slice(0, 8);
  if (!KILITLI[seri]) return json({ ok: false, hata: 'seri' }, 400);

  /* Tek kart doğrulama — anında geri bildirim için */
  if (typeof g.metin === 'string') {
    const s = esles(seri, g.metin);
    return json(s.ok ? { ok: true, kart: s.kart }
                     : { ok: false, sebep: s.sebep, kart: s.kart });
  }

  /* İki kart → kilidi aç */
  if (Array.isArray(g.kanitlar) && g.kanitlar.length === 2) {
    const a = esles(seri, g.kanitlar[0]);
    const b = esles(seri, g.kanitlar[1]);
    if (!a.ok || !b.ok)    return json({ ok: false, sebep: 'dogrulanmadi' });
    if (a.kart === b.kart) return json({ ok: false, sebep: 'ayni' });
    return json({ ok: true, kartlar: KILITLI[seri] });
  }

  return json({ ok: false, hata: 'istek' }, 400);
}
